script:
function calculate() {
  const e = parseFloat(document.getElementById('experimental').value);
  const t = parseFloat(document.getElementById('theoretical').value);
  const r = document.getElementById('result');
  const f = document.getElementById('formula_display');
  const a = document.getElementById('absolute_error');
  if (!isNaN(e) && !isNaN(t) && t !== 0) {
    const abs = Math.abs(e - t);
    const pct = (abs / Math.abs(t)) * 100;
    r.textContent = formatNumber(pct) + '%';
    if (a) a.textContent = formatNumber(abs);
    if (f) f.textContent = '(|' + e + ' - ' + t + '| ÷ |' + t + '|) × 100 = ' + formatNumber(pct) + '%';
  } else {
    r.textContent = '?';
    if (a) a.textContent = '?';
    if (f) f.textContent = '';
  }
}

function formatNumber(n) {
  return Number.isInteger(n) ? n.toString() : parseFloat(n.toFixed(4)).toString();
}
